import moment from 'moment-timezone';

/**
 * Gets date range for today
 *
 * @param {string} timezone - timezone to use for calculations
 *
 * @returns {array} range - array of range as [ start, end ]
 */
export function getToday(timezone) {
  const aMoment = timezone ? moment().tz(timezone) : moment();

  return [aMoment.clone().startOf('day'), aMoment.clone().endOf('day')];
}

/**
 * Gets date range for yesterday
 *
 * @param {string} timezone - timezone to use for calculations
 *
 * @returns {array} range - array of range as [ start, end ]
 */
export function getYesterday(timezone) {
  const aMoment = timezone ? moment().tz(timezone) : moment();

  aMoment.subtract(1, 'day');

  return [aMoment.clone().startOf('day'), aMoment.clone().endOf('day')];
}

/**
 * Gets a date range for a given number of days
 *
 * @param {integer} numberOfDays - The number of last days.
 * @param {string} timezone - timezone to use for calculations
 *
 * @returns {array} range - array of range as [ start, end ]
 */
export function getLastDaysRange(numberOfDays, timezone) {
  const aMoment = timezone ? moment().tz(timezone) : moment();

  return [
    aMoment.clone().subtract(numberOfDays, 'day').startOf('day'),
    aMoment.clone().endOf('day'),
  ];
}

/**
 * Gets date range for this week
 *
 * @param {string} timezone - timezone to use for calculations
 *
 * @returns {array} range - array of range as [ start, end ]
 */
export function getThisWeek(timezone) {
  const aMoment = timezone ? moment().tz(timezone) : moment();

  return [
    aMoment.clone().weekday(0).startOf('day'),
    aMoment.clone().endOf('day'),
  ];
}

/**
 * Gets date range for last week
 *
 * @param {string} timezone - timezone to use for calculations
 *
 * @returns {array} range - array of range as [ start, end ]
 */
export function getLastWeek(timezone) {
  const aMoment = timezone ? moment().tz(timezone) : moment();

  aMoment.subtract(1, 'weeks');

  const start = aMoment.clone().weekday(0).startOf('day');
  const end = aMoment.clone().weekday(6).endOf('day');

  return [start, end];
}

/**
 * Gets date range for this month
 *
 * @param {string} timezone - timezone to use for calculations
 *
 * @returns {array} range - array of range as [ start, end ]
 */
export function getThisMonth(timezone) {
  const aMoment = timezone ? moment().tz(timezone) : moment();

  return [aMoment.clone().startOf('month'), aMoment.clone().endOf('day')];
}

/**
 * Gets date range for last month
 *
 * @param {string} timezone - timezone to use for calculations
 *
 * @returns {array} range - array of range as [ start, end ]
 */
export function getLastMonth(timezone) {
  const aMoment = timezone ? moment().tz(timezone) : moment();

  aMoment.subtract(1, 'months');

  return [
    aMoment.clone().startOf('month').startOf('day'),
    aMoment.clone().endOf('month').endOf('day'),
  ];
}

/**
 * Gets a date range for a given number of months
 *
 * @param {integer} numberOfMonths - The number of last months.
 * @param {string} timezone - timezone to use for calculations
 *
 * @returns {array} range - array of range as [ start, end ]
 */
export function getLastMonthsRange(numberOfMonths, timezone) {
  const aMoment = timezone ? moment().tz(timezone) : moment();

  return [
    aMoment
      .clone()
      .subtract(numberOfMonths, 'months')
      .startOf('month')
      .startOf('day'),
    aMoment.clone().subtract(1, 'months').endOf('month').endOf('day'),
  ];
}

/**
 * Gets date range for this year
 *
 * @param {string} timezone - timezone to use for calculations
 *
 * @returns {array} range - array of range as [ start, end ]
 */
export function getThisYear(timezone) {
  const aMoment = timezone ? moment().tz(timezone) : moment();

  return [
    aMoment.clone().startOf('year').startOf('day'),
    aMoment.clone().endOf('day'),
  ];
}

/**
 * Gets date range for last year
 *
 * @param {string} timezone - timezone to use for calculations
 *
 * @returns {array} range - array of range as [ start, end ]
 */
export function getLastYear(timezone) {
  const aMoment = timezone ? moment().tz(timezone) : moment();

  aMoment.subtract(1, 'years');

  return [
    aMoment.clone().startOf('year').startOf('day'),
    aMoment.clone().endOf('year').endOf('day'),
  ];
}

/**
 * Aligns date range to recent week for isRelativeDateRange.
 *
 * @param {array} range - array of timestamps as [ start, end ]
 * @param {string} timezone - timezone to use for calculations
 *
 * @returns {array} range - aligned array of timestamps as [ start, end ]
 */
export function alignTimeStampsToRecentWeek(range, timezone) {
  const [startTimestamp, endTimestamp] = range;
  if (!startTimestamp || !endTimestamp) {
    return range;
  }

  const startMoment = moment.unix(startTimestamp).tz(timezone);
  const endMoment = moment.unix(endTimestamp).tz(timezone);
  const today = moment().tz(timezone).startOf('day');

  const weeksToAdd = Math.floor(today.diff(endMoment, 'weeks', true));
  startMoment.add(weeksToAdd, 'weeks');
  endMoment.add(weeksToAdd, 'weeks');

  // unlike other functions in this file, this returns timestamps
  return [startMoment.unix(), endMoment.unix()];
}
